import{_ as a,C as s,o as n,c as i,j as t,a as d,E as r,a2 as l}from"./chunks/framework.sc8Z_ZE3.js";const _=JSON.parse('{"title":"Knowledge storage and embedding model","description":"","frontmatter":{},"headers":[],"relativePath":"install/knowledge-storage.md","filePath":"install/knowledge-storage.md"}'),c={name:"install/knowledge-storage.md"};function h(p,e,g,m,u,k){const o=s("Badge");return n(),i("div",null,[e[0]||(e[0]=t("h1",{id:"knowledge-storage-and-embedding-model",tabindex:"-1"},[d("Knowledge storage and embedding model "),t("a",{class:"header-anchor",href:"#knowledge-storage-and-embedding-model","aria-label":'Permalink to "Knowledge storage and embedding model"'},"​")],-1)),r(o,{type:"built",text:"Built"}),e[1]||(e[1]=l(` Knowledge needs two things from the installation: an <strong>object store</strong> for the originals of every source, and, for search by meaning, an <strong>embedding model</strong>. Both are set by the operator in the environment or the Helm values. There is no setting for them in the app.<h2 id="object-store" tabindex="-1">Object store <a class="header-anchor" href="#object-store" aria-label="Permalink to &quot;Object store&quot;">​</a></h2><p>Knowledge keeps the originals (pages, files, documents) in an S3-compatible object store. The search index itself lives in PostgreSQL.</p><p><strong>Docker Compose</strong> brings its own object store inside the stack, with no port outside it. Nothing to do: the bucket is called <code>oe-knowledge</code>, and its data stays in a Docker volume until <code>docker compose down -v</code>.</p><p><strong>Kubernetes:</strong> set the store in <code>my-values.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">objectStore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  endpoint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://s3.eu-central-1.amazonaws.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # any S3-compatible endpoint</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  bucket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">my-octryx-knowledge</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  region</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">eu-central-1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              # empty: model.awsRegion</span></span></code></pre></div><p>The pod needs access to the bucket: IRSA or workload identity through <code>serviceAccount.annotations</code>, or keys in the Secret. With an endpoint, the bucket is required. With no endpoint, Knowledge answers <code>needs_configuration</code>.</p><p>Other installs set the environment directly:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>OCTRYX_KNOWLEDGE_OBJECT_ENDPOINT_URL</code></td><td>required; also for AWS S3 (<code>https://s3.&lt;region&gt;.amazonaws.com</code>), so no implicit endpoint decides where the data lands</td></tr><tr><td><code>OCTRYX_KNOWLEDGE_OBJECT_BUCKET</code></td><td>required</td></tr><tr><td><code>OCTRYX_KNOWLEDGE_OBJECT_REGION</code></td><td>the region</td></tr><tr><td><code>OCTRYX_KNOWLEDGE_OBJECT_PREFIX</code></td><td>optional key prefix: lower-case segments separated by <code>/</code>, at most 64 characters</td></tr><tr><td><code>OCTRYX_KNOWLEDGE_OBJECT_TIMEOUT_SECONDS</code></td><td>optional, 0.5 to 60, default 10</td></tr><tr><td><code>OCTRYX_KNOWLEDGE_OBJECT_AWS_PROFILE</code></td><td>optional: a dedicated credentials profile for the store, so it never uses <code>AWS_*</code> keys meant for another purpose, such as Bedrock</td></tr></tbody></table><p>Credentials are never part of this configuration. They come from the usual AWS credential chain (or the profile) and never appear in a log or a response.</p><h2 id="embedding-model" tabindex="-1">Embedding model <a class="header-anchor" href="#embedding-model" aria-label="Permalink to &quot;Embedding model&quot;">​</a></h2><p>Search always finds passages by their words. With an embedding model, it also finds them by meaning, and fuses both results. Without one, the search stays lexical: it still answers, and the vector part reports <code>needs_configuration</code>. The Docker Compose stack has no embedding model, so its search is lexical.</p><p>The model is chosen per installation with <code>OCTRYX_KNOWLEDGE_EMBEDDING_SPACE</code>. Only the spaces in the platform&#39;s catalog are accepted; an unknown name is <code>needs_configuration</code> too.</p><table tabindex="0"><thead><tr><th>Space</th><th>Model</th><th>Runs</th><th>Dimensions</th></tr></thead><tbody><tr><td><code>local_mlminilm_384_v1</code></td><td>paraphrase-multilingual-MiniLM-L12-v2 (ONNX)</td><td>in the platform&#39;s process: no text leaves it</td><td>384</td></tr><tr><td><code>bedrock_titan2_1024_v1</code></td><td>Amazon Titan Text Embeddings v2</td><td>AWS Bedrock</td><td>1024</td></tr><tr><td><code>bedrock_cohere_ml3_1024_v1</code></td><td>Cohere Embed Multilingual v3</td><td>AWS Bedrock</td><td>1024</td></tr></tbody></table><p><strong>Local space.</strong> The model is never downloaded at runtime. Its files must lie in <code>&lt;model root&gt;/local_mlminilm_384_v1/</code>, where the model root is <code>OCTRYX_KNOWLEDGE_EMBEDDING_MODEL_ROOT</code> (default <code>/app/models/embedding</code>). Every file must match the checksum pinned in the catalog; a missing or altered file is <code>needs_configuration</code>. <code>deployment/local/acceptance/prepare_models.py --space local_mlminilm_384_v1 --root &lt;folder&gt;</code> in the repository downloads the pinned files, checks them and puts them in place. Mount that folder at the model root. The platform loads the model in the background right after its start, so the first search does not wait for it.</p><p><strong>Bedrock spaces.</strong> They use the AWS credentials of the platform and the region from <code>OCTRYX_KNOWLEDGE_EMBEDDING_REGION</code>, else <code>AWS_REGION</code>. Text leaves the platform, so a Workspace may use them only if its data classification is <strong>internal</strong> or lower. A Workspace with a higher or no classification is refused before any text is sent. See <a href="/docs/security/data-classes">Data classes</a>.</p><p><strong>Dimensions.</strong> <code>OCTRYX_KNOWLEDGE_EMBEDDING_DIMENSION</code> (default 1024) sets the vector column when a new PostgreSQL database is created. Set it before the first start.</p><p><strong>Changing the space</strong> means embedding again into a new index; vectors of two spaces are never mixed.</p><p>On Kubernetes, set these variables through <code>extraEnv</code> in <code>my-values.yaml</code>. The chart has no volume for the local model&#39;s files yet, so a Bedrock space is the way there today.</p><h2 id="what-people-see-without-it" tabindex="-1">What people see without it <a class="header-anchor" href="#what-people-see-without-it" aria-label="Permalink to &quot;What people see without it&quot;">​</a></h2><ul><li><strong>Without an object store</strong>, Knowledge search, uploads and syncs do not work: they answer <code>needs_configuration</code>. Only an admin can fix it, by setting the store as above and restarting the server. <strong>Knowledge › Search</strong> says so: <ul><li>to an admin: &quot;Knowledge storage is not set up on this instance&quot;, with the link <strong>How to set up knowledge storage</strong> to this page;</li><li>to everyone else: &quot;Knowledge search is not available yet. Your administrator has not set up knowledge storage on this instance yet.&quot;</li></ul></li><li><strong>When the store is configured but cannot be reached</strong>, the search says &quot;Knowledge storage is not reachable right now. Try the search again in a moment.&quot;</li><li><strong>Without an embedding model</strong>, search works by words only. Results still carry their source file and section.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/install/kubernetes">Install on Kubernetes</a></li><li><a href="/docs/knowledge/guide">Knowledge guide</a></li><li><a href="/docs/start/troubleshooting#installing-on-kubernetes">Troubleshooting</a></li></ul>`,27))])}const E=a(c,[["render",h]]);export{_ as __pageData,E as default};
